makeMtLab(document.getElementById("lab-l12"),{id:"l12",scenarios:[{"label": "Ví dụ: Dựng cây thời gian", "note": "Mỗi tầng trừ một nhóm tổn thất.", "steps": [{"t": "Kế hoạch 450 phút", "html": "<div class=\"mt-bars\"><div><span>Kế hoạch<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>450 phút<\/em><\/span><\/div><\/div>"}, {"t": "Trừ 60 phút dừng", "html": "<div class=\"mt-bars\"><div><span>Kế hoạch<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>450<\/em><\/span><\/div><div><span>Chạy<\/span><span><i class=\"w\" style=\"width:86.7%\"><\/i><em>390<\/em><\/span><\/div><\/div>", "ask": {"q": "Máy dừng 40 phút hỏng và 20 phút chờ. Thời gian chạy?", "o": ["410", "390", "350"], "a": 1}}, {"t": "Chạy tịnh", "html": "<div class=\"mt-bars\"><div><span>Kế hoạch<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>450<\/em><\/span><\/div><div><span>Chạy<\/span><span><i class=\"w\" style=\"width:86.7%\"><\/i><em>390<\/em><\/span><\/div><div><span>Chạy tịnh<\/span><span><i class=\"o\" style=\"width:77.8%\"><\/i><em>350<\/em><\/span><\/div><\/div>", "ask": {"q": "10 500 hộp × 2,0 s là bao nhiêu phút?", "o": ["350", "390", "175"], "a": 0}}, {"t": "Hữu ích", "html": "<div class=\"mt-bars\"><div><span>Thời gian kế hoạch<\/span><span><i class=\"\" style=\"width:100.0%\"><\/i><em>450 phút<\/em><\/span><\/div><div><span>Thời gian chạy<\/span><span><i class=\"w\" style=\"width:86.7%\"><\/i><em>390 phút<\/em><\/span><\/div><div><span>Thời gian chạy tịnh<\/span><span><i class=\"o\" style=\"width:77.8%\"><\/i><em>350 phút<\/em><\/span><\/div><div><span>Thời gian hữu ích<\/span><span><i class=\"\" style=\"width:75.6%\"><\/i><em>340 phút<\/em><\/span><\/div><\/div>", "say": "<p>Mỗi khoảng hụt giữa hai thanh là một nhóm tổn thất.<\/p>"}]}, {"label": "Ví dụ: Xếp tổn thất vào nhóm", "note": "Sẵn sàng, hiệu suất hay chất lượng?", "steps": [{"t": "Kẹt vít tải 25 phút", "html": "<p class=\"mt-calc\">→ <b>Sẵn sàng<\/b> (hỏng máy)<\/p>"}, {"t": "Chạy 2,3 s/hộp thay vì 2,0", "html": "<p class=\"mt-calc\">→ <b>Hiệu suất<\/b> (chạy chậm)<\/p>", "ask": {"q": "Chạy chậm thuộc nhóm nào?", "o": ["Sẵn sàng", "Hiệu suất", "Chất lượng"], "a": 1}}, {"t": "Hộp thiếu khối lượng", "html": "<p class=\"mt-calc\">→ <b>Chất lượng<\/b><\/p>"}]}, {"label": "Ví dụ: OEE từ cây thời gian", "note": "OEE = hữu ích / kế hoạch.", "steps": [{"t": "Hữu ích 340, kế hoạch 450", "html": "<p class=\"mt-calc\">340 / 450<\/p>"}, {"t": "Kết quả", "html": "<p class=\"mt-calc\">≈ <b>0,7556<\/b> = 75,56 %<\/p>", "ask": {"q": "340/450 xấp xỉ bao nhiêu?", "o": ["0,7556", "0,8667", "0,9714"], "a": 0}}]}, {"label": "Bẫy: Tính chạy tịnh bằng số đạt", "note": "Chạy tịnh dùng tổng số đếm, kể cả hộp lỗi.", "steps": [{"t": "Dùng 10 200 × 2,0 s", "html": "<p class=\"mt-calc\">= 340 phút → tưởng là chạy tịnh<\/p>"}, {"t": "Sửa: dùng 10 500", "html": "<p class=\"mt-calc\">Chạy tịnh = 350; hữu ích mới là 340<\/p>", "say": "<p>Nếu dùng số đạt, tổn thất chất lượng bị nhập vào tổn thất hiệu suất.<\/p>"}]}, {"label": "Lỗi: Tính giờ nghỉ vào tổn thất", "note": "Giờ nghỉ không nằm trong cây.", "steps": [{"t": "Bắt đầu từ 480 phút", "html": "<p class=\"mt-calc\">OEE = 340 / 480 ≈ 0,7083<\/p>"}, {"t": "Sửa: bắt đầu từ thời gian kế hoạch", "html": "<p class=\"mt-calc\">OEE = 340 / 450 ≈ 0,7556<\/p>", "say": "<p>Giờ nghỉ là dừng có kế hoạch, đã trừ trước khi tính.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l12"),"l12",[{"kind": "num", "t": "Các tầng thời gian", "d": "<p>Ca kế hoạch 420 phút, máy chạy 360 phút, chu kỳ lý tưởng 2,0 s, 9 900 hộp đạt, 150 hộp lỗi. Trả lời bằng phút hoặc tỷ số (4 chữ số thập phân).<\/p>", "items": [{"q": "Thời gian chạy tịnh (phút)?", "a": 335, "unit": "phút"}, {"q": "Thời gian hữu ích (phút)?", "a": 330, "unit": "phút"}, {"q": "OEE?", "a": 0.7857, "tol": 5e-05}], "hints": ["Chạy tịnh = (đạt + lỗi) × chu kỳ / 60.", "Hữu ích = đạt × chu kỳ / 60.", "OEE = hữu ích / kế hoạch."], "why": "10 050 × 2 / 60 = 335; 9 900 × 2 / 60 = 330; 330 / 420 ≈ 0,7857."}, {"kind": "pick", "t": "Tổn thất thuộc nhóm nào?", "d": "<p>Xếp sáu tổn thất lớn vào ba nhóm.<\/p>", "cats": ["Sẵn sàng", "Hiệu suất", "Chất lượng"], "items": [{"q": "Hỏng động cơ băng tải", "a": 0}, {"q": "Đổi sản phẩm mất 15 phút", "a": 0}, {"q": "Kẹt hộp, gỡ trong 20 giây", "a": 1}, {"q": "Giảm tốc vì hạt ẩm", "a": 1}, {"q": "Hộp in sai date", "a": 2}, {"q": "Hộp lỗi ngay sau khi khởi động lại", "a": 2}], "hints": ["Dừng lâu và chuyển đổi: sẵn sàng.", "Dừng ngắn và chạy chậm: hiệu suất.", "Sản phẩm lỗi: chất lượng."], "why": "Hỏng, chuyển đổi → sẵn sàng; dừng ngắn, chạy chậm → hiệu suất; lỗi quá trình và lỗi khởi động → chất lượng."}, {"kind": "order", "t": "Cây thời gian từ trên xuống", "d": "<p>Sắp xếp các tầng từ lớn nhất tới nhỏ nhất.<\/p>", "items": ["Thời gian ca", "Thời gian kế hoạch", "Thời gian chạy", "Thời gian chạy tịnh", "Thời gian hữu ích"], "hints": ["Mỗi tầng dưới trừ đi một nhóm tổn thất.", "Thời gian hữu ích chỉ tính hộp đạt."], "why": "Ca → kế hoạch → chạy → chạy tịnh → hữu ích."}]);
mesSim(document.getElementById("sim-l12"),Object.assign({id:"l12"},{kind:"calc",title:"Cây thời gian của máy M1",sub:"Mỗi tầng trừ một nhóm tổn thất. Chỉnh số liệu ca để thấy tầng nào co lại.",
 inputs:[{k:"plan",l:"Thời gian kế hoạch",min:300,max:480,step:10,v:450,u:"phút"},{k:"down",l:"Dừng không kế hoạch",min:0,max:150,step:5,v:60,u:"phút"},
  {k:"tot",l:"Tổng số đếm",min:6000,max:13500,step:100,v:10500,u:"hộp"},{k:"bad",l:"Hộp lỗi",min:0,max:1000,step:10,v:300,u:"hộp"},{k:"cyc",l:"Chu kỳ lý tưởng",min:1.5,max:2.5,step:0.1,v:2,u:"s"}],
 outputs:[{k:"run",l:"Thời gian chạy",f:V=>V.plan-V.down,fmt:v=>mesFmt(v)+" phút"},{k:"net",l:"Chạy tịnh = tổng × chu kỳ",f:V=>V.tot*V.cyc/60,fmt:v=>mesFmt(v,1)+" phút"},
  {k:"use",l:"Hữu ích = đạt × chu kỳ",f:V=>(V.tot-V.bad)*V.cyc/60,fmt:v=>mesFmt(v,1)+" phút"},{k:"oee",l:"OEE = hữu ích / kế hoạch",big:1,f:(V,R)=>R.use/V.plan,fmt:v=>mesPct(v),cls:v=>v>1?"er":""}],
 bars:(V,R)=>[["Kế hoạch",V.plan,"a",mesFmt(V.plan)+" ph"],["Chạy",R.run,"a",mesFmt(R.run)+" ph"],["Chạy tịnh",R.net,R.net>R.run?"er":"wa",mesFmt(R.net,1)+" ph"],["Hữu ích",R.use,"ok",mesFmt(R.use,1)+" ph"]],
 tasks:[{t:"Đọc cây với số liệu ca chuẩn: tổn thất hiệu suất là bao nhiêu phút?",ok:"390 − 350 = 40 phút; tổn thất chất lượng 350 − 340 = 10 phút; OEE = 340 / 450 ≈ 75,6 %.",check:s=>s.V.down===60&&s.V.tot===10500&&Math.abs(s.R.oee-0.7556)<0.001},
  {t:"Cho tổng số đếm lên 13 000 hộp mà không đổi thời gian dừng. Có gì bất thường?",ok:"Chạy tịnh 433 phút lớn hơn thời gian chạy 390: máy “nhanh hơn lý tưởng”, dữ liệu sai (Bài 14).",check:s=>s.R.net>s.R.run},
  {t:"Đặt lại 10 500 hộp và giảm dừng còn 30 phút. OEE tăng bao nhiêu?",ok:"OEE không đổi nếu số hộp không đổi! Bớt dừng chỉ có ích khi thời gian thêm được dùng để làm thêm hộp.",check:s=>s.V.down===30&&s.V.tot===10500}]}));

